async Task ImportAsync(string[] files, CancellationToken ct)
{
    foreach (var f in files)
    {
        ct.ThrowIfCancellationRequested();              // check between files
        var text = await File.ReadAllTextAsync(f, ct); // and pass it down
        Parse(text);                                    // synchronous work
    }
}
